-- Personal-device regression fixtures. All rows/config changes are rolled back.
\set ON_ERROR_STOP on
BEGIN;
UPDATE public.deployment_policy SET hosted=true;
CREATE FUNCTION pg_temp.expect_error(statement text, fragment text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE message text;
BEGIN
  BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS message=MESSAGE_TEXT; END;
  IF message IS NULL OR position(fragment IN message)=0 THEN RAISE EXCEPTION 'Expected rejection [%], got [%]',fragment,message; END IF;
END;
$$;
GRANT EXECUTE ON FUNCTION pg_temp.expect_error(text,text) TO authenticated,anon;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
INSERT INTO auth.users(id,email) VALUES('10000000-0000-0000-0000-000000000001','owner@hardening.invalid'),('10000000-0000-0000-0000-000000000002','member@hardening.invalid');
CREATE TEMP TABLE fixture AS SELECT id AS workspace_id,owner_id FROM public.workspaces WHERE owner_id IN ('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002');
GRANT SELECT ON fixture TO authenticated,anon;
UPDATE public.workspaces SET plan='team',is_beta=false,trial_expires_at=NULL WHERE id IN(SELECT workspace_id FROM fixture);
INSERT INTO public.workspace_members(workspace_id,user_id,role) SELECT workspace_id,'10000000-0000-0000-0000-000000000002','member' FROM fixture WHERE owner_id='10000000-0000-0000-0000-000000000001';
INSERT INTO public.agents(id,workspace_id,name,model,provider) SELECT '20000000-0000-0000-0000-000000000001',workspace_id,'Fixture','default','openai' FROM fixture WHERE owner_id='10000000-0000-0000-0000-000000000001';
INSERT INTO public.teams(id,workspace_id,name) SELECT '20000000-0000-0000-0000-000000000002',workspace_id,'Fixture team' FROM fixture WHERE owner_id='10000000-0000-0000-0000-000000000001';

UPDATE public.agents SET config='{"execution":{"kind":"external","agent":"codex","transport":"cli"}}' WHERE id='20000000-0000-0000-0000-000000000001';
CREATE TEMP TABLE pairing AS SELECT public.start_device_pairing(repeat('a',64),'ABCDEFGH23','Fixture laptop','codex:cli',repeat('e',64)) AS id;
GRANT SELECT ON pairing TO authenticated;
DO $$ BEGIN IF (public.exchange_device_pairing((SELECT id FROM pairing),repeat('a',64),repeat('b',64))->>'pending')<>'true' THEN RAISE EXCEPTION 'Pairing did not wait for browser approval'; END IF; END $$;
UPDATE public.device_pairings SET last_poll_at=NULL WHERE id=(SELECT id FROM pairing);
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claims','{"role":"anon"}',true);
SELECT pg_temp.expect_error($q$SELECT public.approve_device_pairing('ABCDEFGH23',NULL,ARRAY['20000000-0000-0000-0000-000000000001']::uuid[])$q$,'permission denied');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SELECT pg_temp.expect_error($q$SELECT public.approve_device_pairing('ABCDEFGH23','99999999-9999-4999-8999-999999999999',ARRAY['20000000-0000-0000-0000-000000000001']::uuid[])$q$,'selected workspace');
SELECT pg_temp.expect_error($q$SELECT public.approve_device_pairing('ABCDEFGH23',(SELECT workspace_id FROM fixture WHERE owner_id=auth.uid()),ARRAY['20000000-0000-0000-0000-000000000002']::uuid[])$q$,'runtime or workspace');
SELECT public.approve_device_pairing('ABCDEFGH23',(SELECT workspace_id FROM fixture WHERE owner_id=auth.uid()),ARRAY['20000000-0000-0000-0000-000000000001']::uuid[]);
SELECT pg_temp.expect_error($q$SELECT credential_hash FROM public.personal_devices$q$,'permission denied');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT pg_temp.expect_error($q$SELECT public.exchange_device_pairing((SELECT id FROM pairing),repeat('c',64),repeat('b',64))$q$,'expired or reused');
SELECT public.exchange_device_pairing((SELECT id FROM pairing),repeat('a',64),repeat('b',64));
SELECT pg_temp.expect_error($q$SELECT public.exchange_device_pairing((SELECT id FROM pairing),repeat('a',64),repeat('b',64))$q$,'expired or reused');
UPDATE public.agents SET config=config||jsonb_build_object('paired_device_id',(SELECT device_id FROM public.device_pairings WHERE id=(SELECT id FROM pairing))) WHERE id='20000000-0000-0000-0000-000000000001';
SELECT pg_temp.expect_error($q$INSERT INTO public.tasks(id,workspace_id,title,assigned_agent_id,status,created_by,actor_type,actor_id) SELECT '30000000-0000-0000-0000-000000000001',workspace_id,'API spoof','20000000-0000-0000-0000-000000000001','dispatched',owner_id,'api_key','fixture-key' FROM fixture WHERE owner_id='10000000-0000-0000-0000-000000000001'$q$,'initiating user');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
SELECT pg_temp.expect_error($q$INSERT INTO public.tasks(id,workspace_id,title,assigned_agent_id,status,created_by) SELECT '30000000-0000-0000-0000-000000000002',workspace_id,'Other member','20000000-0000-0000-0000-000000000001','dispatched',auth.uid() FROM fixture WHERE owner_id='10000000-0000-0000-0000-000000000001'$q$,'initiating user');
SELECT pg_temp.expect_error($q$SELECT public.revoke_personal_device((SELECT id FROM public.personal_devices LIMIT 1))$q$,'Device unavailable');
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
INSERT INTO public.tasks(id,workspace_id,title,assigned_agent_id,status,created_by) SELECT '30000000-0000-0000-0000-000000000003',workspace_id,'Own device job','20000000-0000-0000-0000-000000000001','dispatched',auth.uid() FROM fixture WHERE owner_id=auth.uid();
RESET ROLE;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.claim_next_task()) THEN RAISE EXCEPTION 'Generic runner claimed a personal job'; END IF; END $$;
CREATE TEMP TABLE job AS SELECT public.claim_personal_job(repeat('b',64)) AS data;
DO $$ BEGIN IF (SELECT data->>'id' FROM job)<>'30000000-0000-0000-0000-000000000003' THEN RAISE EXCEPTION 'Wrong personal job claimed'; END IF; END $$;
SELECT public.heartbeat_personal_job(repeat('b',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job));
SELECT pg_temp.expect_error($q$SELECT public.heartbeat_personal_job(repeat('c',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job))$q$,'revoked');
SELECT pg_temp.expect_error($q$SELECT public.write_personal_job(repeat('b',64),'30000000-0000-0000-0000-000000000003','99999999-9999-4999-8999-999999999999',1,'stale','completed')$q$,'superseded');
SELECT pg_temp.expect_error($q$SELECT public.write_personal_job(repeat('b',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job),3,'gap','stream')$q$,'sequence gap');
SELECT public.write_personal_job(repeat('b',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job),1,'partial','stream');
SELECT public.write_personal_job(repeat('b',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job),1,'partial','stream');
SELECT pg_temp.expect_error($q$SELECT public.write_personal_job(repeat('b',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job),1,'changed','stream')$q$,'replay');
-- Consent and lease checks still run for duplicate stream snapshots.
UPDATE public.personal_worker_leases SET expires_at=now()-interval '1 second' WHERE task_id='30000000-0000-0000-0000-000000000003';
SELECT pg_temp.expect_error($q$SELECT public.write_personal_job(repeat('b',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job),1,'partial','stream')$q$,'lease expired');
UPDATE public.personal_worker_leases SET expires_at=now()+interval '15 seconds' WHERE task_id='30000000-0000-0000-0000-000000000003';
UPDATE public.personal_devices SET approved_until=now()-interval '1 second';
SELECT pg_temp.expect_error($q$SELECT public.heartbeat_personal_job(repeat('b',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job))$q$,'revoked');
UPDATE public.personal_devices SET approved_until=now()+interval '30 days';
UPDATE public.workspaces SET suspended_at=now() WHERE id=(SELECT workspace_id FROM fixture WHERE owner_id='10000000-0000-0000-0000-000000000001');
SELECT pg_temp.expect_error($q$SELECT public.heartbeat_personal_job(repeat('b',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job))$q$,'revoked');
UPDATE public.workspaces SET suspended_at=NULL WHERE id=(SELECT workspace_id FROM fixture WHERE owner_id='10000000-0000-0000-0000-000000000001');
SELECT pg_temp.expect_error($q$SELECT public.personal_job_attachment(repeat('b',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job),'99999999-9999-4999-8999-999999999999')$q$,'Attachment unavailable');
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.execution_attempts WHERE job_id='30000000-0000-0000-0000-000000000003' AND backend='personal') THEN RAISE EXCEPTION 'Laptop compute mislabeled as managed'; END IF; END $$;
SELECT public.write_personal_job(repeat('b',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job),2,'completed result','completed');
SELECT public.write_personal_job(repeat('b',64),'30000000-0000-0000-0000-000000000003',(SELECT (data->>'attemptId')::uuid FROM job),2,'completed result','completed');
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.tasks WHERE id='30000000-0000-0000-0000-000000000003' AND status='completed' AND result='"completed result"'::jsonb AND metadata->'execution'->>'usageKnown'='false') THEN RAISE EXCEPTION 'Native completion or unknown usage lost'; END IF; END $$;
SELECT public.rotate_personal_credential(repeat('b',64),repeat('c',64));
SELECT pg_temp.expect_error($q$SELECT public.claim_personal_job(repeat('b',64))$q$,'revoked');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
INSERT INTO public.tasks(id,workspace_id,title,assigned_agent_id,status,created_by) SELECT '30000000-0000-0000-0000-000000000004',workspace_id,'Revoke in flight','20000000-0000-0000-0000-000000000001','dispatched',auth.uid() FROM fixture WHERE owner_id=auth.uid();
RESET ROLE;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
UPDATE job SET data=public.claim_personal_job(repeat('c',64));
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SELECT public.revoke_personal_device((SELECT id FROM public.personal_devices LIMIT 1));
RESET ROLE;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT pg_temp.expect_error($q$SELECT public.write_personal_job(repeat('c',64),'30000000-0000-0000-0000-000000000004',(SELECT (data->>'attemptId')::uuid FROM job),1,'revived','completed')$q$,'revoked');
SELECT public.maintain_personal_jobs();
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.tasks WHERE id='30000000-0000-0000-0000-000000000004' AND status='failed' AND error LIKE '%uncertain%') THEN RAISE EXCEPTION 'Revoked attempt not failed honestly'; END IF; END $$;
SELECT pg_temp.expect_error($q$UPDATE public.tasks SET status='dispatched' WHERE id='30000000-0000-0000-0000-000000000004'$q$,'new run');
-- Deleting a member account retires its job in a workspace owned by someone else.
CREATE TEMP TABLE member_pairing AS SELECT public.start_device_pairing(repeat('d',64),'MEMBERCD23','Member laptop','codex:cli',repeat('f',64)) AS id;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
SELECT public.approve_device_pairing('MEMBERCD23',(SELECT workspace_id FROM fixture WHERE owner_id='10000000-0000-0000-0000-000000000001'),ARRAY['20000000-0000-0000-0000-000000000001']::uuid[]);
RESET ROLE;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT public.exchange_device_pairing((SELECT id FROM member_pairing),repeat('d',64),repeat('d',64));
UPDATE public.agents SET config=config||jsonb_build_object('paired_device_id',(SELECT device_id FROM public.device_pairings WHERE id=(SELECT id FROM member_pairing))) WHERE id='20000000-0000-0000-0000-000000000001';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
INSERT INTO public.tasks(id,workspace_id,title,assigned_agent_id,status,created_by) SELECT '30000000-0000-0000-0000-000000000005',workspace_id,'Delete member account','20000000-0000-0000-0000-000000000001','dispatched',auth.uid() FROM fixture WHERE owner_id='10000000-0000-0000-0000-000000000001';
RESET ROLE;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
DELETE FROM public.personal_devices WHERE user_id='10000000-0000-0000-0000-000000000002';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.tasks WHERE id='30000000-0000-0000-0000-000000000005' AND status='failed' AND execution_device_id IS NULL AND error LIKE '%No API fallback%') THEN RAISE EXCEPTION 'Deleted member device job could enter the API queue'; END IF; END $$;
DELETE FROM auth.users WHERE id='10000000-0000-0000-0000-000000000002';
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.tasks WHERE id='30000000-0000-0000-0000-000000000005') THEN RAISE EXCEPTION 'Deleted account job survived the existing user cascade'; END IF; END $$;
-- Invalid pairing lookups consume a durable signed-user budget.
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SELECT public.inspect_device_pairing('WRONGCODE2') FROM generate_series(1,12);
RESET ROLE;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.device_pairing_budgets WHERE key_hash='review:10000000-0000-0000-0000-000000000001' AND used=10) THEN RAISE EXCEPTION 'Failed lookups did not retain their review budget'; END IF; END $$;
ROLLBACK;
